const T='Consolidate_ALL!';
let start=4000;
const segs:[string,string,string][]=[['A','A','A'],['C','G','B'],['N','R','G']];
for (const [n,last] of [['Jack',2000],['Henry',1000],['Richard',1001]] as [string,number][]) {
  const count=last-1, end=start+count-1;
  for (const [a,b,d] of segs) {
    const dEnd=String.fromCharCode(d.charCodeAt(0)+b.charCodeAt(0)-a.charCodeAt(0));
    wb.getRange(`${T}${d}${start}:${dEnd}${end}`).copyFrom(wb.getRange(`${n}!${a}2:${b}${last}`),{type:'values'});
  }
  wb.getRange(`${T}A${start}:L${end}`).copyFrom(wb.getRange(`${T}A2:L${count+1}`),{type:'formats'});
  wb.getRange(`${T}L${start}:L${end}`).setValues(Array.from({length:count},()=>[n]));
  if (n==='Richard') wb.getRange(`${T}A${start}:A${end}`).getStyle().setNumberFormat('[$-C09]dd\\-mmm\\-yy;@');
  log(n,start,end);
